/**
 * Golden contract for the SM-18 format-read port follow-up on `.KNO`
 * collection descriptors (sm18-re gitlab #43).
 *
 * Follow-up to #36. The fixture
 * `test/fixtures/sm18-port-format-read-kno.json` is a mirror of
 * `sm18-re:tests/fixtures/port-format-read-kno.json`, regenerated by
 * `sm18-re:scripts/export-port-format-read-kno-fixture.py` across every
 * captured `.KNO` under `artifacts/supermemo/systems/`.
 *
 * This file is brief-writer owned. The lane adds
 *
 *   parseKno(bytes: Uint8Array): KnoRecord
 *
 * to `src/sm18-format-read.ts` additively. One 950-byte descriptor per file,
 * no header.
 *
 * Only four members are defended:
 *
 *   element_count         u32 @ 0x00
 *   deleted_element_count u32 @ 0x04
 *   next_element_id       u32 @ 0x08
 *   format_version        u8  @ 0x0c
 *
 * Everything from 0x0D..950 is `unknown_0x%03x` in 8-byte slices (the last
 * slice is short: `min(8, 950 - offset)`). The port must preserve those
 * slices as `{hex: string}` blobs under their offset-labelled names. Do NOT
 * collapse the tail into one big blob, and do NOT rename a slice — later
 * lanes refine the names in place and will break every follow-up's
 * byte-exact oracle if the port anticipates them.
 *
 * Error contracts:
 * - A `.KNO` whose length is not exactly 950 bytes is an error.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(
  __dirname,
  "fixtures",
  "sm18-port-format-read-kno.json",
);
const MODULE_SPEC = ["..", "src", "sm18-format-read.ts"].join("/");

interface HexBlob {
  hex: string;
}

interface KnoRecord {
  element_count: number;
  deleted_element_count: number;
  next_element_id: number;
  format_version: number;
  [unknown: string]: number | HexBlob;
}

interface FixtureFile {
  collection: string;
  path: string;
  byte_length: number;
  bytes_b64: string;
  record: KnoRecord;
}

interface Fixture {
  schema: number;
  scope: string[];
  record_size: number;
  verified_fields: string[];
  files: FixtureFile[];
}

interface PortModule {
  parseKno: (bytes: Uint8Array) => KnoRecord;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.parseKno !== "function") {
      return null;
    }
    return mod as PortModule;
  } catch {
    return null;
  }
}

function decodeBase64(encoded: string): Uint8Array {
  return new Uint8Array(Buffer.from(encoded, "base64"));
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture declares the kno scope and 950-byte descriptors", () => {
  assert.equal(fixture.schema, 1);
  assert.deepEqual(fixture.scope, ["kno"]);
  assert.equal(fixture.record_size, 950);
  assert.ok(fixture.files.length > 0);
  for (const file of fixture.files) {
    assert.equal(file.byte_length, 950, `${file.path} must be 950 bytes`);
  }
});

test("src/sm18-format-read.ts exports parseKno", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseKno not implemented yet");
    return;
  }
  assert.equal(typeof port.parseKno, "function");
});

test("parseKno throws on a non-950-byte input", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("parseKno not implemented yet");
    return;
  }
  assert.throws(() => port.parseKno(new Uint8Array(949)));
  assert.throws(() => port.parseKno(new Uint8Array(951)));
});

for (const file of fixture.files) {
  test(`format-read-kno: ${file.path} parses to the fixture record`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("parseKno not implemented yet");
      return;
    }
    const bytes = decodeBase64(file.bytes_b64);
    assert.equal(bytes.byteLength, 950, `${file.path} is 950 bytes`);
    const parsed = port.parseKno(bytes);
    assert.deepEqual(
      parsed,
      file.record,
      `record for ${file.path} must match the fixture projection`,
    );
  });
}
